/* @autogenerated */
import { EditConflict } from './edit-conflict.model';
import { applyMerge, chooseMerge, hasPendingConflicts, sameValue, threeWayMerge } from './three-way-merge';

interface Item {
  uid: string;
  name?: string | null;
  description?: string | null;
  owner?: { $ref: string } | null;
  tags?: string[] | null;
  since?: Date | string | null;
  version?: number;
}

const conflictOf = (original: Item, sent: Item, current: Item): EditConflict<Item> => ({ original, sent, current });

const stateOf = (conflict: EditConflict<Item>, field: string) =>
  threeWayMerge(conflict).find((merge) => merge.field === field)?.state;

describe('threeWayMerge', () => {
  const base: Item = { uid: '1', name: 'A', version: 1 };

  it('marks a field nobody changed as unchanged and resolves it to current', () => {
    const [merge] = threeWayMerge(conflictOf(base, { ...base }, { ...base, version: 2 }));
    expect(merge).toEqual(
      jasmine.objectContaining({ field: 'name', state: 'unchanged', choice: 'current', resolved: 'A' }),
    );
  });

  it('marks a field only the user changed as mine and resolves it to sent', () => {
    const [merge] = threeWayMerge(conflictOf(base, { ...base, name: 'Mine' }, { ...base, version: 2 }));
    expect(merge).toEqual(jasmine.objectContaining({ state: 'mine', choice: 'sent', resolved: 'Mine' }));
  });

  it('marks a field only the server changed as theirs and resolves it to current', () => {
    const [merge] = threeWayMerge(conflictOf(base, { ...base }, { ...base, name: 'Theirs', version: 2 }));
    expect(merge).toEqual(jasmine.objectContaining({ state: 'theirs', choice: 'current', resolved: 'Theirs' }));
  });

  it('marks a field both changed to the same value as same', () => {
    const [merge] = threeWayMerge(conflictOf(base, { ...base, name: 'B' }, { ...base, name: 'B', version: 2 }));
    expect(merge).toEqual(jasmine.objectContaining({ state: 'same', choice: 'current', resolved: 'B' }));
  });

  it('marks a field both changed to different values as an unresolved conflict', () => {
    const [merge] = threeWayMerge(conflictOf(base, { ...base, name: 'Mine' }, { ...base, name: 'Theirs' }));
    expect(merge.state).toBe('conflict');
    expect(merge.choice).toBeNull();
    expect('resolved' in merge).toBeFalse();
  });

  it('ignores version and uid by default', () => {
    const fields = threeWayMerge(conflictOf(base, { ...base, version: 5 }, { ...base, uid: '2', version: 9 })).map(
      (merge) => merge.field,
    );
    expect(fields).toEqual(['name']);
  });

  it('accepts a custom ignore list', () => {
    const conflict = conflictOf(
      { ...base, description: 'x' },
      { ...base, description: 'y' },
      { ...base, description: 'z' },
    );
    expect(threeWayMerge(conflict, { ignore: ['description'] }).map((merge) => merge.field)).toEqual([
      'uid',
      'name',
      'version',
    ]);
  });

  it('compares references by $ref', () => {
    const original = { ...base, owner: { $ref: 'a' } };
    expect(stateOf(conflictOf(original, { ...base, owner: { $ref: 'a' } }, original), 'owner')).toBe('unchanged');
    expect(stateOf(conflictOf(original, { ...base, owner: { $ref: 'b' } }, original), 'owner')).toBe('mine');
    expect(
      stateOf(conflictOf(original, { ...base, owner: { $ref: 'b' } }, { ...base, owner: { $ref: 'b' } }), 'owner'),
    ).toBe('same');
  });

  it('compares arrays by content', () => {
    const original = { ...base, tags: ['a', 'b'] };
    expect(stateOf(conflictOf(original, { ...base, tags: ['a', 'b'] }, original), 'tags')).toBe('unchanged');
    expect(stateOf(conflictOf(original, { ...base, tags: ['a'] }, { ...base, tags: ['b'] }), 'tags')).toBe('conflict');
  });

  it('compares dates by instant, also against their ISO string', () => {
    const instant = '2026-01-02T10:00:00.000Z';
    const original = { ...base, since: new Date(instant) };
    expect(stateOf(conflictOf(original, { ...base, since: new Date(instant) }, original), 'since')).toBe('unchanged');
    expect(stateOf(conflictOf(original, original, { ...base, since: instant }), 'since')).toBe('unchanged');
    expect(stateOf(conflictOf(original, original, { ...base, since: new Date('2026-01-03') }), 'since')).toBe('theirs');
  });

  it('treats null, undefined and empty string as equal', () => {
    const original = { ...base, description: null };
    expect(stateOf(conflictOf(original, { ...base, description: '' }, { ...base }), 'description')).toBe('unchanged');
  });
});

describe('sameValue', () => {
  it('distinguishes a reference from an empty value', () => {
    expect(sameValue({ $ref: 'a' }, null)).toBeFalse();
  });

  it('compares nested objects by content', () => {
    expect(sameValue({ a: 1, b: { c: 'x' } }, { b: { c: 'x' }, a: 1 })).toBeTrue();
    expect(sameValue({ a: 1 }, { a: 2 })).toBeFalse();
  });
});

describe('applyMerge', () => {
  const conflict = conflictOf(
    { uid: '1', name: 'A', description: 'd', version: 1 },
    { uid: '1', name: 'Mine', description: 'd', version: 1 },
    { uid: '1', name: 'Theirs', description: 'server', version: 2 },
  );

  it('throws while there are unresolved conflicts', () => {
    const merges = threeWayMerge(conflict);
    expect(hasPendingConflicts(merges)).toBeTrue();
    expect(() => applyMerge(conflict, merges)).toThrowError(/name/);
  });

  it('builds the value from the resolved fields and the current version', () => {
    const merges = threeWayMerge(conflict).map((merge) =>
      merge.state === 'conflict' ? chooseMerge(merge, 'sent') : merge,
    );
    expect(hasPendingConflicts(merges)).toBeFalse();
    expect(applyMerge(conflict, merges)).toEqual({ uid: '1', name: 'Mine', description: 'server', version: 2 });
  });

  it('lets the user override an automatically merged field', () => {
    const merges = threeWayMerge(conflict).map((merge) =>
      merge.field === 'name' ? chooseMerge(merge, 'current') : chooseMerge(merge, 'sent'),
    );
    expect(applyMerge(conflict, merges)).toEqual({ uid: '1', name: 'Theirs', description: 'd', version: 2 });
  });
});
